var forms = [];
var es = new p5.Ease();
var colors = ["#fe4a49", "#fed766", "#009fb7", "#f0f0f0"];

function setup() {
	createCanvas(800, 800);
	rectMode(CENTER);
	strokeWeight(4);
	let seg = 10;
    let w = width / seg;
    for (let i = 0; i < seg; i++) {
        for (let j = 0; j < seg; j++) {
            let x = i * w + w/2;
            let y = j * w + w/2;
			let rnd = int(random(5)+1);
			let off = 0;
			if(rnd == 1){
				forms.push(new Form01(x, y, w - off));
			}
			else if(rnd == 2){
				forms.push(new Form02(x, y, w - off));
			}
			else if(rnd == 3){
				forms.push(new Form03(x, y, w - off));
			}
			else if(rnd == 4){
				forms.push(new Form04(x, y, w - off));
			}
			else if(rnd == 5){
				forms.push(new Form05(x, y, w - off));
			}
        }
    }
}

